def choose_move(observation):
    def clamp_step(v):
        if v > 0:
            return 1
        if v < 0:
            return -1
        return 0

    def first_pos(value):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return None

    def get_pos(keys, default=None):
        for k in keys:
            v = observation.get(k)
            p = first_pos(v)
            if p is not None:
                return p
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    sx_sy = get_pos(["self_position", "position", "agent_position", "self_pos"], (0, 0))
    ox_oy = get_pos(["opponent_position", "enemy_position", "opponent_pos"], None)
    sx, sy = sx_sy
    env = observation.get("environment_name", "") or ""

    grid_w = observation.get("grid_width", observation.get("width", 0)) or 0
    grid_h = observation.get("grid_height", observation.get("height", 0)) or 0

    # Pursuit / evasion
    if env == "pursuit_evasion":
        role = observation.get("self_role", observation.get("role", "pursuer"))
        if role == "evader":
            threats = []
            if ox_oy is not None:
                threats.append(ox_oy)
            for key in ("opponents", "enemies", "predators", "pursuers"):
                vals = observation.get(key) or []
                if isinstance(vals, (list, tuple)):
                    for v in vals:
                        p = first_pos(v)
                        if p is not None:
                            threats.append(p)
            if threats:
                nearest = min(threats, key=lambda p: dist(sx_sy, p))
                move = step_away(sx_sy, nearest)
                if move == [0, 0]:
                    move = [1, 1] if (sx + sy) % 2 == 0 else [-1, -1]
                return move
            return [1 if (sx + sy) % 2 == 0 else -1, 0]
        # pursuer
        if ox_oy is not None:
            return step_toward(sx_sy, ox_oy)
        targets = []
        for key in ("opponents", "prey", "targets"):
            vals = observation.get(key) or []
            if isinstance(vals, (list, tuple)):
                for v in vals:
                    p = first_pos(v)
                    if p is not None:
                        targets.append(p)
        if targets:
            best = min(targets, key=lambda p: dist(sx_sy, p))
            return step_toward(sx_sy, best)
        return [0, 0]

    # Territory control
    if env == "territory_control":
        candidates = []
        for key in ("unclaimed_cells", "neutral_cells", "opponent_territory", "frontier", "targets"):
            vals = observation.get(key) or []
            if isinstance(vals, (list, tuple)):
                for v in vals:
                    p = first_pos(v)
                    if p is not None:
                        candidates.append(p)
        if candidates:
            # Prefer closest contestable cell, but break ties toward map center for flexibility.
            center = (grid_w // 2, grid_h // 2) if grid_w and grid_h else sx_sy
            best = min(candidates, key=lambda p: (dist(sx_sy, p), dist(center, p)))
            return step_toward(sx_sy, best)

        # Fallback: expand toward open space or away from enemy pressure.
        if ox_oy is not None:
            return step_away(sx_sy, ox_oy)
        if grid_w and grid_h:
            center = (grid_w // 2, grid_h // 2)
            return step_toward(sx_sy, center)
        return [0, 0]

    # Resource collection (default)
    resources = []
    for key in ("resources", "resource_positions", "collectibles", "items", "food"):
        vals = observation.get(key) or []
        if isinstance(vals, (list, tuple)):
            for v in vals:
                p = first_pos(v)
                if p is not None:
                    resources.append(p)

    carrying = observation.get("carrying", observation.get("cargo", 0)) or 0
    capacity = observation.get("capacity", observation.get("inventory_capacity", 0)) or 0

    if resources:
        # If loaded, bias toward home/base; otherwise nearest resource.
        if carrying and capacity and carrying >= capacity:
            home = get_pos(["home_position", "base_position", "spawn_position", "start_position"], None)
            if home is not None:
                return step_toward(sx_sy, home)
        best = min(resources, key=lambda p: dist(sx_sy, p))
        return step_toward(sx_sy, best)

    # Denial / fallback: move toward opponent or center.
    if ox_oy is not None:
        return step_toward(sx_sy, ox_oy)
    if grid_w and grid_h:
        return step_toward(sx_sy, (grid_w // 2, grid_h // 2))
    return [0, 0]

